/**
 * [INPUT]: 依赖通知合同类别、ui.js 与本地账户订阅状态。
 * [OUTPUT]: 导出共源收件箱、修订详情、稳定空间深链与账户订阅。
 * [POS]: 账户通知边界；页面与抽屉读取同一演示事件。
 * [PROTOCOL]: Update this header on change, then check AGENTS.md
 */
import * as U from './ui.js';
const { icon, btn, esc, field, panel, pageHeader, badge, select, kv } = U;
export const notificationCategoryIds = ['build', 'release', 'permission', 'device', 'credential', 'account', 'workspace', 'delivery'];
export const notificationCategories = ['构建', '版本', '权限', '设备', '凭据', '账户', '工作空间', '交付'];
const events = [
    { id: 'n-device', category: '设备', glyph: 'monitor', title: 'Mac mini 处于离线状态', summary: 'Orbital · 一个目标正在等待匹配设备。设备恢复后继续排队。', workspace_id: 'orbital', workspace: 'Orbital', project: 'Beacon Mobile', time: '2 分钟前', route: 'node/mini', needs_action: true, severity: 'warning', revision: 1 },
    { id: 'n-release', category: '版本', glyph: 'layers', title: 'Atlas API 1.8.2 已发布', summary: 'Orbital · 正式文件与镜像摘要已固定。', workspace_id: 'orbital', workspace: 'Orbital', project: 'Atlas API', time: '10 分钟前', route: 'release/1.8.2/atlas', needs_action: false, severity: 'success', revision: 1 },
    { id: 'n-build', category: '构建', glyph: 'play', title: '构建 #1048 已生成执行方案', summary: 'Orbital Desktop · 查看当前计划和真实执行阶段。', workspace_id: 'orbital', workspace: 'Orbital', project: 'Orbital Desktop', time: '32 分钟前', route: 'build/1048', needs_action: true, severity: 'running', revision: 2 },
    { id: 'n-permission', category: '权限', glyph: 'users', title: '你已加入 Northstar Studio', summary: '工作空间角色为成员。项目权限由管理员另行授予。', workspace_id: 'northstar', workspace: 'Northstar Studio', project: '', time: '昨天', route: 'tenants', needs_action: false, severity: 'neutral', revision: 1 },
];
export function notificationItems(state) {
    return events.filter(item => !state.noticeRevoked?.[item.id]).map(item => { const revision = state.noticeRevisions?.[item.id] || item.revision, read_revision = state.readNotices?.[item.id] || 0; return { ...item, revision, content_revision: revision, attention_revision: revision, read_revision, unread: read_revision < revision }; });
}
export function notificationList(state, full = true) {
    const mode = state.noticeMode || '全部通知', category = state.noticeType || '全部类型', workspace = state.noticeTenant || '全部工作空间', project = state.noticeProject || '全部项目';
    const all = notificationItems(state).filter(item => (mode !== '未读' || item.unread) && (mode !== '需要关注' || item.needs_action) && (category === '全部类型' || item.category === category) && (workspace === '全部工作空间' || item.workspace === workspace) && (project === '全部项目' || item.project === project)), count = (state.noticePages || 1) * 3, items = all.slice(0, count), next_cursor = all.length > count ? `cursor-${count}` : null;
    const tools = `<div class="toolbar wrap">${select('noticeMode', mode, ['全部通知', '未读', '需要关注'])}${select('noticeType', category, ['全部类型', ...notificationCategories])}${full ? select('noticeTenant', workspace, ['全部工作空间', 'Orbital', 'Northstar Studio']) + select('noticeProject', project, ['全部项目', 'Orbital Desktop', 'Atlas API', 'Beacon Mobile']) : ''}</div>`;
    if (state.noticeLoadError) return `<div class="entry-inbox">${tools}${U.empty('暂时无法读取通知', '当前筛选和已读修订仍保留。', btn('重试读取', 'notice-retry', 'primary', 'refresh'))}</div>`;
    return `<div class="entry-inbox">${tools}<p class="field-help" role="status">已显示 ${items.length} / ${all.length} 条示例 · 按当前授权范围阅读</p>${items.length ? items.map(item => `<button type="button" class="notification-item entry-notice ${item.unread ? 'unread' : ''}" data-action="notice-detail" data-id="${item.id}"><span class="notification-symbol ${item.severity}">${icon(item.glyph, 22)}</span><span class="entry-notice-copy"><strong>${esc(item.title)}</strong><span>${esc(item.summary)}</span><small>${item.category} · ${item.time} · 修订 ${item.content_revision}${item.unread ? ' · 未读' : ' · 已读'}</small></span>${item.unread ? '<span class="unread-dot" aria-label="未读"></span>' : ''}${icon('chevron', 16)}</button>`).join('') : U.empty('这里暂时安静。', '调整筛选，再查看其他通知。')}${next_cursor ? btn('加载更多通知', 'notice-more', 'secondary', 'down', `data-cursor="${next_cursor}"`) : '<p class="field-help">已到当前筛选窗口末尾。</p>'}<p class="field-help">页面与抽屉共用事件及阅读修订。游标在此只作本地分页示例。</p><details><summary>预览通知更新与异常</summary><div class="row wrap mt">${btn('更新构建通知内容', 'notice-revision', 'secondary', 'refresh', 'data-id="n-build"')}${btn('模拟读取失败', 'notice-error', 'ghost', 'warn')}${btn('恢复演示权限', 'notice-restore', 'ghost', 'shield')}</div></details></div>`;
}
export function renderNotificationPage(state) { return pageHeader('YOUR INBOX', '需要关注的，都在这里。', `账户收件箱 · 跨工作空间 · ${notificationItems(state).filter(item => item.unread).length} 条未读`, btn('通知设置', 'notification-settings', 'secondary', 'settings') + btn('全部已读', 'mark-read', 'primary', 'check')) + panel(notificationList(state)); }
export function notificationDetail(state, id) {
    const item = notificationItems(state).find(event => event.id === id);
    if (!item) return U.empty('通知已不可用', '当前权限已变化。业务正文与对象地址已移除。', btn('返回收件箱', 'notifications', 'secondary', 'arrowLeft'));
    const baseline = events.find(event => event.id === id).revision;
    return `<div class="stack">${badge(item.category, item.severity)}<h3>${esc(item.title)}</h3><p>${esc(item.summary)}</p>${item.revision > baseline ? '<p class="notice">此通知的内容已更新。再次阅读后，当前修订标为已读。</p>' : ''}${kv('工作空间', esc(item.workspace))}${kv('项目', esc(item.project || '工作空间范围'))}${kv('内容修订 / 已读修订', `${item.content_revision} / ${item.read_revision}`)}<p class="field-help">${item.time} · 打开业务对象时再次校验权限。</p><a class="btn primary" href="#${item.route}" data-route="${item.route}" data-workspace-context="${item.workspace_id}">打开业务对象 ${icon('arrow', 16)}</a><details><summary>事件历史与权限状态</summary><p class="section-note">${esc(item.title)} · 修订 ${item.revision}</p>${btn('模拟失去此对象权限', 'notice-revoke', 'danger', 'shield', `data-id="${item.id}"`)}</details></div>`;
}
export function subscriptionFields(state) {
    const preferences = state.accountNotifications || {}, email = preferences.email_address || '', verified = !!preferences.email_verified;
    return `<div class="stack"><section><h3>邮件订阅</h3><p class="field-help">邮箱独立于登录用户名。验证后逐类启用邮件。</p><form data-form="account-email">${field('接收邮箱', `<input class="input" name="address" type="email" maxlength="254" value="${esc(email)}" placeholder="只填写虚构邮箱" required>`)}<button class="btn secondary" type="submit">${email ? '更新邮箱' : '保存邮箱'}</button></form>${email ? `<div class="row wrap mt">${badge(verified ? '已验证' : '待验证', verified ? 'success' : 'warning')}${!verified ? btn('预览验证确认', '', 'secondary', 'mail', 'data-route="email-verify/demo"') : ''}${btn('移除邮箱', 'account-email-remove', 'ghost', 'close')}</div>` : ''}</section><form data-form="account-subscriptions"><h3>事件偏好</h3><div class="entry-preference-table"><div><strong>事件</strong><strong>站内</strong><strong>邮件</strong></div>${notificationCategories.map((category, i) => `<div><span>${category}</span><label><span class="sr-only">${category}站内通知</span><input class="checkbox" type="checkbox" name="in_app.${i}" ${preferences.in_app?.[notificationCategoryIds[i]] !== false ? 'checked' : ''}></label><label><span class="sr-only">${category}邮件通知</span><input class="checkbox" type="checkbox" name="email.${i}" ${preferences.email?.[notificationCategoryIds[i]] ? 'checked' : ''} ${verified ? '' : 'disabled'}></label></div>`).join('')}</div>${field('通知语言', select('locale', preferences.locale || 'zh-CN', [{ value: 'zh-CN', label: '简体中文' }, { value: 'en', label: 'English' }]))}<button class="btn primary" type="submit">保存订阅 ${icon('check', 16)}</button></form></div>`;
}
